input.content:
import json
import re
import subprocess

SRC = "/home/ertval/code/project-modules/keel-multi-agent-pipeline/apps/web/lib/api.ts"

src = open(SRC).read()
start = src.index("export const MOCK_RECONCILIATION: Reconciliation = {")
end = src.index("\n};", start) + 3
literal = src[start:end]

ts = "/tmp/opencode/_mock_extract.ts"
open(ts, "w").write(
    "const m = " + literal.split("=", 1)[1].strip().rstrip(";")
    + ";\nconsole.log(JSON.stringify(m));\n"
)

out = subprocess.run(
    ["node", "--experimental-strip-types", ts],
    capture_output=True,
    text=True,
    cwd="/home/ertval/code/project-modules/keel-multi-agent-pipeline/apps/web",
)
if out.returncode != 0:
    print("node failed:\n", out.stderr[:3000])
    raise SystemExit(1)

mock = json.loads(out.stdout)
live = json.load(open("/tmp/opencode/voyage_001.json"))["reconciliation"]

diffs = []


def walk(a, b, path=""):
    if type(a) is not type(b) and not (
        isinstance(a, (int, float)) and isinstance(b, (int, float))
    ):
        diffs.append(f"{path}: type mock={type(a).__name__} live={type(b).__name__}")
        return
    if isinstance(a, dict):
        for k in sorted(set(a) | set(b)):
            if k not in a:
                diffs.append(f"{path}.{k}: MISSING in mock (live={json.dumps(b[k])[:90]})")
            elif k not in b:
                diffs.append(f"{path}.{k}: EXTRA in mock (mock={json.dumps(a[k])[:90]})")
            else:
                walk(a[k], b[k], f"{path}.{k}")
    elif isinstance(a, list):
        if len(a) != len(b):
            diffs.append(f"{path}: length mock={len(a)} live={len(b)}")
            return
        for i, (x, y) in enumerate(zip(a, b)):
            walk(x, y, f"{path}[{i}]")
    else:
        if a != b:
            diffs.append(f"{path}: mock={json.dumps(a)[:110]} live={json.dumps(b)[:110]}")


walk(mock, live, "reconciliation")

if not diffs:
    print("MOCK_RECONCILIATION vs live GET /voyages/voyage_001 .reconciliation")
    print("IDENTICAL: 0 divergences across every field, key and list length.")
else:
    print(f"{len(diffs)} divergence(s):")
    for d in diffs:
