test("served output sweep", async ({ page }) => {
  await page.goto("/login");
  await page.getByRole("button", { name: /Enter Demo Mode/i }).click();
  await expect(page).toHaveURL(/\/dashboard$/);

  for (const route of ROUTES) {
    await page.goto(route);
    await page.waitForTimeout(1800);
    const body = await page.evaluate(() => document.body.innerText);
    const html = await page.content();
    console.log(`\n########## ${route} (${body.length} chars) ##########`);

    for (const f of FORBIDDEN) {
      const hits = (body.match(new RegExp(f, "g")) || []).length;
      const inHtml = (html.match(new RegExp(f, "g")) || []).length;
      if (hits || inHtml) {
        console.log(`  !! ${f}: innerText=${hits} html=${inHtml}`);
        for (const line of body.split("\n")) {
          if (line.includes(f)) console.log(`     > ${line.trim().slice(0, 200)}`);
        }
      } else {
        console.log(`  ok  ${f}: absent`);
      }
    }

    // raw sentinels
    for (const s of ["p.null", "NaN", "undefined", "[object Object]"]) {
      const hits = (body.match(new RegExp(s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g")) || []).length;
      if (hits) {
        console.log(`  !! SENTINEL ${s} x${hits}`);
        for (const line of body.split("\n")) {
          if (line.includes(s)) console.log(`     > ${line.trim().slice(0, 200)}`);
        }
      } else {
        console.log(`  ok  sentinel ${s}: absent`);
      }
    }
    const nullWord = body.split("\n").filter((l) => /(^|\s)null(\s|$)/i.test(l.trim()));
    if (nullWord.length) {
      console.log(`  !! raw 'null' on ${nullWord.length} line(s)`);
      for (const l of nullWord.slice(0, 6)) console.log(`     > ${l.trim().slice(0, 200)}`);
    } else {
      console.log("  ok  raw 'null': absent");
    }

    if (route === "/voyage/voyage_001/reconcile") {
      const page$ = await page.evaluate(() => document.body.innerText);
      for (const needle of [
        "$187,000",
        "$62,000",
        "$112,000",
        "14 June 2026",
        "15 June 2026",
        "16 June 2026",
        "Owner position better supported",
        "Charterer position better supported",
      ]) {
        console.log(`  ${page$.includes(needle) ? "ok " : "!! MISSING"} ${needle}`);
      }
    }
  }
});

import { expect, test } from "@playwright/test";

test("day labels + soc2 context", async ({ page }) => {
  await page.goto("/login");
  await page.getByRole("button", { name: /Enter Demo Mode/i }).click();
  await expect(page).toHaveURL(/\/dashboard$/);

  await page.goto("/voyage/voyage_001/reconcile");
  await expect(page.locator("#reconciled-total-display")).toHaveText("$112,000");

  console.log("=== day cards: textContent of the assessment badge ===");
  for (const d of ["2026-06-14", "2026-06-15", "2026-06-16"]) {
    const card = page.locator(`#day-card-${d}`);
    const badge = card.locator(".badge").first();
    console.log(
      `  ${d}: innerText="${await badge.innerText()}" textContent="${await badge.textContent()}"`
    );
    console.log(`      heading: "${await card.locator("h3").textContent()}"`);
  }

  console.log("\n=== reconciled-total band badges (day labels) ===");
  const band = page.locator("#reconciled-total-band");
  console.log(
    (await band.locator(".badge").allTextContents())
      .map((t) => `  "${t}"`)
      .join("\n")
  );

  console.log("\n=== header badge ===");
  console.log("  " + (await page.locator("header .badge").first().innerText()));

  console.log("\n=== three-part day card, exact rendered text (day 16) ===");
  await page.locator("#clause-toggle-2026-06-16").click();
  const expanded = page.locator("#day-card-2026-06-16");
  console.log(
    (await expanded.innerText())
      .split("\n")
      .map((l) => "  | " + l)
      .join("\n")
  );

  console.log("\n=== SOC 2 context on / ===");
  await page.goto("/");
  const ctx = await page.evaluate(() => {
    const el = [...document.querySelectorAll("*")].find((n) =>
      n.children.length === 0 && n.textContent?.includes("SOC 2")
    );
    return el ? { tag: el.tagName, text: el.textContent, parentText: el.parentElement?.textContent } : null;
  });
  console.log("  " + JSON.stringify(ctx));

  console.log("\n=== BIMCO mentions in served output (all routes) ===");
  for (const route of ["/", "/login", "/voyage/voyage_001/reconcile", "/voyage/voyage_001", "/voyage/voyage_001/letter"]) {
    await page.goto(route);
    await page.waitForTimeout(1500);
    const lines = await page.evaluate(() =>
      document.body.innerText.split("\n").filter((l) => /BIMCO/i.test(l)).map((l) => l.trim())
    );
    console.log(`  ${route}: ${lines.length ? JSON.stringify(lines) : "none"}`);
  }
});

